// Run with Node on PATH, WARDEN_BIN set to a freshly built CLI, and
// WARDEN_MCP_SDK pointing at a prepared @modelcontextprotocol/sdk package.
import {spawn,spawnSync} from "node:child_process";
import {mkdtemp,mkdir,writeFile,readFile,copyFile} from "node:fs/promises";
import {tmpdir} from "node:os";
import {join,resolve} from "node:path";
import {pathToFileURL,fileURLToPath} from "node:url";
import readline from "node:readline";
import assert from "node:assert/strict";
const bin=process.env.WARDEN_BIN;if(!bin)throw Error("WARDEN_BIN required");
const root=await mkdtemp(join(tmpdir(),"warden-growth-smoke-"));const runtime=join(root,"runtime"),data=join(root,"data"),priv=join(root,"private");for(const p of [runtime,data,priv])await mkdir(p,{mode:0o700});
const entry=join(runtime,"fixture.mjs");await copyFile(fileURLToPath(new URL("bridge-server.mjs",import.meta.url)),entry);const allowed=join(data,"hello.txt"),outside=join(root,"outside.txt");await writeFile(allowed,"hello fixture");await writeFile(outside,"outside fixture");
const env={...process.env,HOME:priv,XDG_CONFIG_HOME:priv,XDG_STATE_HOME:priv,WARDEN_GATEWAY_TOKEN:"fixture-token-"+"x".repeat(48)};
const policy=join(priv,"policy.yaml"),rules=join(priv,"rules.json"),journal=join(priv,"journal.jsonl"),control=join(priv,"control.json");await writeFile(policy,`filesystem:\n  read: ${JSON.stringify([runtime,data])}\nnetwork: {allow: []}\nenv: {allow: []}\nlimits: {memory_mb: 512, timeout_s: 60}\n`);await writeFile(rules,JSON.stringify({version:1,tools:{read:{},write:{}},resources:[],prompts:[],timeout_seconds:10}));
const args=["--rules",rules,"--policy",policy,"--backend","linux","--journal",journal,"--",process.execPath,entry];
const msg=(id,method,params)=>({jsonrpc:"2.0",id,method,...(params?{params}:{})});const init=id=>msg(id,"initialize",{protocolVersion:"2025-11-25",capabilities:{},clientInfo:{name:"smoke",version:"1"}});
const checks=[];
function cli(args,pass=true){const r=spawnSync(bin,args,{env,encoding:"utf8",timeout:60000});assert.equal(r.status===0,pass,r.stderr);return r}
async function workflow(call){const list=await call("tools/list");assert.deepEqual(list.result.tools.map(t=>t.name),["read","write"]);const good=await call("tools/call",{name:"read",arguments:{path:allowed}});assert.equal(good.result.isError,undefined);assert.match(good.result.content[0].text,/hello fixture/);const deny=await call("tools/call",{name:"erase",arguments:{path:allowed}});assert.equal(deny.error.code,-32001);const write=await call("tools/call",{name:"write",arguments:{path:allowed,content:"escape"}});assert.equal(write.result.isError,true);const read=await call("tools/call",{name:"read",arguments:{path:outside}});assert.equal(read.result.isError,true);assert.equal(await readFile(allowed,"utf8"),"hello fixture")}
// First stdio client: handwritten line-delimited JSON-RPC host.
const proc=spawn(bin,["connect",...args],{env,stdio:["pipe","pipe","pipe"]});let stderr="";proc.stderr.on("data",b=>stderr+=b);let id=0;const pending=new Map();readline.createInterface({input:proc.stdout}).on("line",line=>{const m=JSON.parse(line);pending.get(m.id)?.(m);pending.delete(m.id)});const rpc=(method,params)=>new Promise((resolve,reject)=>{const n=++id;const timer=setTimeout(()=>{pending.delete(n);reject(Error(`RPC timeout: ${stderr}`))},15000);pending.set(n,m=>{clearTimeout(timer);resolve(m)});proc.stdin.write(JSON.stringify(msg(n,method,params))+"\n")});
try{assert.equal((await rpc("initialize",init(0).params)).error,undefined);proc.stdin.write(JSON.stringify({jsonrpc:"2.0",method:"notifications/initialized"})+"\n");await workflow(rpc);checks.push("raw stdio allowed/blocked workflow")}finally{proc.stdin.end();await new Promise(resolve=>proc.on("exit",resolve))}
// Authenticated HTTP listener plus explicit stop control.
const server=spawn(bin,["serve","--token-env","WARDEN_GATEWAY_TOKEN","--listen","127.0.0.1:0","--control-file",control,...args],{env,stdio:["ignore","ignore","pipe"]});let endpoint;let logs="";server.stderr.on("data",b=>{logs+=b});
try{
for(let i=0;i<100;i++){try{const r=JSON.parse(await readFile(control,"utf8"));endpoint=new URL("/mcp",r.url).href;break}catch{await new Promise(r=>setTimeout(r,50))}}if(!endpoint)throw Error("serve readiness: "+logs);
let session;let hid=100;const http=async(method,params)=>{const body=msg(++hid,method,params);const r=await fetch(endpoint,{method:"POST",headers:{Authorization:`Bearer ${env.WARDEN_GATEWAY_TOKEN}`,"Content-Type":"application/json",Accept:"application/json, text/event-stream","MCP-Protocol-Version":"2025-11-25",...(session?{"Mcp-Session-Id":session}:{})},body:JSON.stringify(body)});if(method==="initialize")session=r.headers.get("mcp-session-id");assert.equal(r.status,200,await r.clone().text());return r.json()};
assert.equal((await fetch(endpoint,{method:"POST",body:"{}"})).status,401);await http("initialize",init(0).params);const notified=await fetch(endpoint,{method:"POST",headers:{Authorization:`Bearer ${env.WARDEN_GATEWAY_TOKEN}`,"Content-Type":"application/json",Accept:"application/json, text/event-stream","MCP-Protocol-Version":"2025-11-25","Mcp-Session-Id":session},body:JSON.stringify({jsonrpc:"2.0",method:"notifications/initialized"})});assert.equal(notified.status,202);await workflow(http);checks.push("raw HTTP allowed/blocked workflow");
// Second independent implementation: the official TypeScript MCP SDK.
const sdk=process.env.WARDEN_MCP_SDK;if(!sdk)throw Error("WARDEN_MCP_SDK required for SDK gate");const load=part=>import(pathToFileURL(join(sdk,"dist/esm/client",part)).href);const {Client}=await load("index.js");const {StreamableHTTPClientTransport}=await load("streamableHttp.js");const {StdioClientTransport}=await load("stdio.js");
for(const kind of ["stdio","http"]){const client=new Client({name:"warden-sdk-smoke",version:"1"},{capabilities:{}});const transport=kind==="stdio"?new StdioClientTransport({command:bin,args:["connect",...args],env,stderr:"pipe"}):new StreamableHTTPClientTransport(new URL(endpoint),{requestInit:{headers:{Authorization:`Bearer ${env.WARDEN_GATEWAY_TOKEN}`}}});try{await client.connect(transport);assert.deepEqual((await client.listTools()).tools.map(t=>t.name),["read","write"]);assert.match((await client.callTool({name:"read",arguments:{path:allowed}})).content[0].text,/hello fixture/);await assert.rejects(client.callTool({name:"erase",arguments:{path:allowed}}));assert.equal((await client.callTool({name:"write",arguments:{path:allowed,content:"blocked"}})).isError,true);assert.equal((await client.callTool({name:"read",arguments:{path:outside}})).isError,true);checks.push(`official MCP SDK ${kind} allowed/blocked workflow`)}finally{await client.close()}}
// Evidence must be valid only for its exact trusted, fresh, unrevoked inputs.
const key=join(priv,"issuer.key"),manifest=join(priv,"checks.json"),evidence=join(priv,"evidence.json"),revocations=join(priv,"revocations.json");await writeFile(manifest,JSON.stringify({version:1,checks:[{name:"allowed read",method:"tools/call",params:{name:"read",arguments:{path:allowed}},decision:"allow",contains:"hello fixture"},{name:"blocked erase",method:"tools/call",params:{name:"erase",arguments:{path:allowed}},decision:"deny"}]}));cli(["creator","keygen","--output",key]);const shared=["--policy",policy,"--rules",rules,"--artifact",runtime,"--manifest",manifest];cli(["creator","check",...shared,"--key",key,"--output",evidence,"--backend","linux","--",process.execPath,entry]);await writeFile(revocations,JSON.stringify({version:1,expires_at:new Date(Date.now()+3600000).toISOString(),revoked_evidence:[],revoked_artifacts:[]}));const verify=["creator","verify",...shared,"--public-key",key+".pub","--revocations",revocations,"--evidence",evidence];cli([...verify,"--badge",join(priv,"checks-passing.svg"),"--",process.execPath,entry]);await writeFile(entry,(await readFile(entry,"utf8"))+"\n// changed artifact\n");cli([...verify,"--",process.execPath,entry],false);checks.push("signed creator checks, trusted verification, artifact-drift refusal");
cli(["stop","--control-file",control]);await new Promise((resolve,reject)=>{server.on("exit",resolve);setTimeout(()=>reject(Error("stop cleanup timeout")),10000).unref()});checks.push("authenticated emergency stop");
assert.equal(await readFile(allowed,"utf8"),"hello fixture");console.log(JSON.stringify({status:"pass",backend:"linux",protocol:"2025-11-25",checks,evidenceDirectory:root}));
}finally{server.kill("SIGTERM")}
